NativeSignal sys1_probe_text_encoding(VM& vm, Thread& thread) {
    const uint32_t address = thread.stack.pop();
    if (address == 0) {
        throw std::runtime_error("Sys1:0x27 string must not be null");
    }
    const std::string text = vm.memory().read_cstring(address, thread.base);
    const TextEncoding encoding = detect_text_encoding(text);
    thread.stack.push(
        encoding == TextEncoding::Utf8
            ? 1U
            : (encoding == TextEncoding::SingleByte ? 0x80000000U : 0U));
    return NativeSignal::Continue;
}
